\label{thm:lasserobermaierref}
The following are equivalent:
\begin{itemize}\itemsep=0pt
 \item[$(i)$] $P_n(x)=P_n^{(1/(2c_1)-3/2)}(x), \qquad n\in\mathbb{N}_0$,
  \item[$(ii)$] $P_n^\prime(x)=P_n^\prime(1)P_{n-1}^{\ast}(x),\qquad n\in\mathbb{N}$.
 \end{itemize}

\label{thm:ismailobermaiercontref}
Let $q\in(0,1)$, $\beta\in(0,1/\sqrt{q})$ and $A=\sqrt{\beta}/2+1/(2\sqrt{\beta})$. Moreover, let $(Q_n(x))_{n\in\mathbb{N}_0}$ be orthogonal with respect to a symmetric probability Borel measure~$\mu$ on $\mathbb{R}$ with $|\mathsf{supp}\,\mu|=\infty$ and $\mathsf{supp}\,\mu\subseteq[-A,A]$; furthermore, let $(Q_n(x))_{n\in\mathbb{N}_0}$ be normalized by $Q_n(A)=1(n\in\mathbb{N}_0)$, and let $Q_2(0)=-\beta(1-q)/\big(1-\beta^2 q\big)$. Then the following are equivalent:
\begin{itemize}\itemsep=0pt
\item[$(i)$] $Q_n(x)=P_n(x;\beta|q),\qquad n\in\mathbb{N}_0$,
\item[$(ii)$] $(\mathcal{D}_q Q_n(x))_{n\in\mathbb{N}}$ is orthogonal with respect to $\big(A^2-x^2\big)\mathrm{d}\mu(x)$.
\end{itemize}

\label{thm:maincontqultrasph2}
Under the conditions of Theorem~{\rm \ref{thm:ismailobermaiercontref}} and the additional assumption that $\beta\leq1$, the following are equivalent: \begin{itemize}\itemsep=0pt
\item[$(i)$] $Q_n(x)=P_n(x;\beta|q)$, $n\in\mathbb{N}_0$,
\item[$(ii)$] the quotient \[
\frac{\int_\mathbb{R}\mathcal{A}_q Q_{n+1}(x)Q_{n-1}(x)\mathrm{d}\mu(x)}{\int_\mathbb{R}\mathcal{D}_q Q_{n+1}(x)Q_n(x)\mathrm{d}\mu(x)}\] is independent of $n\in\mathbb{N}$.
\end{itemize}

\label{thm:mainsieved}
For every $k\in\mathbb{N}$, $n\in\mathbb{N}_0$ and $i\in\{0,\ldots,k-1\}$, one has
\begin{equation}\label{eq:mainsievedintheorem}
P_{k n+i}(x;k)=\sum_{j=0}^{\lfloor\frac{n}{2}\rfloor}[p_n(j)T_{k n-2j k-i}(x)+q_n(j)T_{k n-2j k+i}(x)].
\end{equation}
Moreover, one has
\begin{align}
\label{eq:rpqin} r_n(j)&=p_{n-1}(j-1)+q_{n-1}(j), \qquad n\in\mathbb{N},\quad j\in\left\{0,\ldots,\left\lfloor\frac{n}{2}\right\rfloor\right\},\\
\label{eq:rpqout} q_n(j)&=r_n(j)-p_n(j), \qquad n\in\mathbb{N}_0, \quad j\in\left\{0,\ldots,\left\lfloor\frac{n}{2}\right\rfloor\right\},\\
\label{eq:psum} p_n(j)&=\sum_{i=0}^j[r_n(i)-r_{n+1}(i)], \qquad n\in\mathbb{N}_0, \quad j\in\left\{0,\ldots,\left\lfloor\frac{n}{2}\right\rfloor\right\}.
\end{align}

et $k\geq2$ first. We establish the expansion \eqref{eq:mainsievedintheorem} via induction on $n\in\mathbb{N}_0$. It is clear from the recurrence relation for the Chebyshev polynomials of the first kind that $P_i(x;k)=T_i(x)$ for all $i\in\{0,\ldots,k\}$, so \eqref{eq:mainsievedintheorem} is true for $n=0$. Now let $n\in\mathbb{N}$ be arbitrary but fixed and assume the validity of \eqref{eq:mainsievedintheorem} for $n-1$. In particular, we then have
\begin{equation*}
P_{k n-2}(x;k)=\sum_{j=0}^{\lfloor\frac{n-1}{2}\rfloor}[p_{n-1}(j)T_{k n-2j k-2k+2}(x)+q_{n-1}(j)T_{k n-2j k-2}(x)].
\end{equation*}
Due to \eqref{eq:specialdefinition1} and \eqref{eq:specialdefinition2}, the latter equation can be rewritten as
\begin{equation}\label{eq:rec1a}
P_{k n-2}(x;k)=\sum_{j=0}^{\lfloor\frac{n}{2}\rfloor}[p_{n-1}(j-1)T_{k n-2j k+2}(x)+q_{n-1}(j)T_{k n-2j k-2}(x)].
\end{equation}
In the same way, we obtain
\begin{equation}\label{eq:rec1b}
P_{k n-1}(x;k)=\sum_{j=0}^{\lfloor\frac{n}{2}\rfloor}[p_{n-1}(j-1)T_{k n-2j k+1}(x)+q_{n-1}(j)T_{k n-2j k-1}(x)].
\end{equation}
We now use that $P_{k m}(x;k)=P_m(T_k(x))$, $m\in\mathbb{N}_0$ \cite[Theorem 1, Section VI]{GvA88}, which yields
\begin{equation}\label{eq:rec2}
P_{k n}(x;k)=\sum_{j=0}^{\lfloor\frac{n}{2}\rfloor}r_n(j)T_{n-2j}(T_k(x))=\sum_{j=0}^{\lfloor\frac{n}{2}\rfloor}r_n(j)T_{k n-2j k}(x).
\end{equation}
Combining \eqref{eq:rec1a}, \eqref{eq:rec1b} and \eqref{eq:rec2} with the relation
$2x P_{k n-1}(x;k)=P_{k n}(x;k)+P_{k n-2}(x;k)$ and using the recurrence relation for the Chebyshev polynomials of the first kind, we obtain that $r_n(j)=p_{n-1}(j-1)+q_{n-1}(j)$ for each $j\in\{0,\ldots,\left\lfloor n/2\right\rfloor\}$. Since
\begin{equation*}
p_{n-1}(j-1)+q_{n-1}(j)=p_n(j)+q_n(j)
\end{equation*}
for each $j\in\{0,\ldots,\left\lfloor n/2\right\rfloor\}$ (which makes use of the recursions \eqref{eq:recnew1} and \eqref{eq:recnew2}, as well as another use of definition \eqref{eq:specialdefinition2}), we therefore get
\begin{equation}\label{eq:rec2mod}
P_{k n}(x;k)=\sum_{j=0}^{\lfloor\frac{n}{2}\rfloor}[p_n(j)+q_n(j)]T_{k n-2j k}(x).
\end{equation}
We now combine \eqref{eq:rec1b} with \eqref{eq:rec2mod}, write
\begin{equation*}
2x T_{k n-2j k}(x)=T_{kn-2j k+1}(x)+T_{|k n-2j k-1|}(x), \qquad j\in\left\{0,\ldots,\left\lfloor\frac{n}{2}\right\rfloor\right\},
\end{equation*}
use \eqref{eq:recnew1}, \eqref{eq:recnew2} and definition \eqref{eq:specialdefinition2} again and obtain
\begin{align*}
2a_n P_{k n+1}(x;k)&=2x P_{k n}(x;k)-2c_n P_{k n-1}(x;k)\\
&=\sum_{j=0}^{\lfloor\frac{n}{2}\rfloor}[p_n(j)+q_n(j)-2c_n p_{n-1}(j-1)]T_{k n-2j k+1}(x)\\
&\quad+\sum_{j=0}^{\lfloor\frac{n}{2}\rfloor}[p_n(j)+q_n(j)-2c_n q_{n-1}(j)]T_{|k n-2j k-1|}(x)\\
&=2a_n\sum_{j=0}^{\lfloor\frac{n}{2}\rfloor}[p_n(j)T_{k n-2j k-1}(x)+q_n(j)T_{k n-2j k+1}(x)].
\end{align*}
Thus if $k=2$, then \eqref{eq:mainsievedintheorem} is shown. If $k\geq3$, we use induction on $i$ to prove that
\begin{equation}\label{eq:conrec1ind}
P_{k n+i}(x;k)=\sum_{j=0}^{\lfloor\frac{n}{2}\rfloor}[p_n(j)T_{k n-2j k-i}(x)+q_n(j)T_{k n-2j k+i}(x)], \qquad i\in\{0,\ldots,k-1\}
\end{equation}
and have already shown the initial step $i\in\{0,1\}$; we hence assume $i\in\{0,\ldots,k-3\}$ to be arbitrary but fixed and \eqref{eq:conrec1ind} to hold for $i,i+1$, and then calculate
\begin{align*}
P_{k n+i+2}(x;k)&=2x P_{k n+i+1}(x;k)-P_{k n+i}(x;k)\\
&=\sum_{j=0}^{\lfloor\frac{n}{2}\rfloor}[p_n(j)T_{k n-2j k-i-2}(x)+q_n(j)T_{k n-2j k+i+2}(x)].
\end{align*}
This finishes the proof of \eqref{eq:mainsievedintheorem} for $k\geq2$, and we have simultaneously established \eqref{eq:rpqin} and~\eqref{eq:rpqout}. \eqref{eq:mainsievedintheorem} for the remaining case $k=1$ is an immediate consequence of \eqref{eq:rpqout}. Finally, \eqref{eq:psum} can be seen as follows: let $n\in\mathbb{N}_0$ and $j\in\{0,\ldots,\left\lfloor n/2\right\rfloor\}$. By \eqref{eq:rpqin} and \eqref{eq:rpqout}, we have
\begin{equation*}
r_n(i)-r_{n+1}(i)=p_n(i)-p_n(i-1)
\end{equation*}
for all $i\in\{0,\ldots,j\}$. Taking the sum from $0$ to $j$ and using definition \eqref{eq:specialdefinition1}, we get
\begin{equation*}
\sum_{i=0}^j[r_n(i)-r_{n+1}(i)]=\sum_{i=0}^j[p_n(i)-p_n(i-1)]=p_n(j)
\end{equation*}
as desired.

\label{example:sievedultrasph}
Let $P_n(x)=P_n^{(\alpha)}(x)$, $n\in\mathbb{N}_0$, be the sequence of ultraspherical polynomials which corresponds to $\alpha>-1$. The case $\alpha=-1/2$ corresponds to the Chebyshev polynomials of the first kind $(T_n(x))_{n\in\mathbb{N}_0}$ and is therefore trivial, so let $\alpha\neq-1/2$ from now on. Then $(r_n)_{n\in\mathbb{N}_0}$ is given by \cite[Theorem 9.1.1]{Is09}
\begin{equation}\label{eq:rsievedultrasph}
r_n(j)=\begin{cases} \displaystyle\binom{n}{\frac{n}{2}}\frac{\left(\alpha+\frac{1}{2}\right)_{\frac{n}{2}}^2}{(2\alpha+1)_n}, & n\quad\text{even and}\quad j=\frac{n}{2}, \\ \displaystyle  2\binom{n}{j}\frac{\left(\alpha+\frac{1}{2}\right)_j\left(\alpha+\frac{1}{2}\right)_{n-j}}{(2\alpha+1)_n}, & \text{else}. \end{cases}
\end{equation}
Applying \eqref{eq:psum}, via induction on $j$ we see that the relation between $(p_n)_{n\in\mathbb{N}_0}$ and $(r_n)_{n\in\mathbb{N}_0}$ becomes especially easy and reads
\begin{equation}\label{eq:psievedultrasph}
p_n(j)=\begin{cases} 0, & n\quad \text{even and}\quad j=\frac{n}{2}, \\ \dfrac{2j+2\alpha+1}{2n+4\alpha+2}r_n(j), & \text{else}. \end{cases}
\end{equation}
Theorem~\ref{thm:mainsieved}, \eqref{eq:rsievedultrasph} and \eqref{eq:psievedultrasph} allow an explicit computation of the sieved ultraspherical polynomials \smash{$\big(P_n^{(\alpha)}(x;k)\big)_{n\in\mathbb{N}_0}$}.

\label{thm:mainsievedaskeywilson}
If $k\geq2$, then the following are equivalent:
\begin{enumerate}\itemsep=0pt
\item[$(i)$] $(P_n(x))_{n\in\mathbb{N}_0}$ is $k$-sieved,
\item[$(ii)$] $\mathrm{D}_k P_n(x)=\mathrm{D}_k P_n(1)P_{n-1}^{\ast}(x)$, $n\in\mathbb{N}$,
\item[$(iii)$] $\big(1-x^2\big)\mathrm{D}_k P_n(x)$ is orthogonal to $P_0(x),\ldots,P_{n-2}(x)$, $n\geq2$,
\item[$(iv)$] one has
\begin{equation*}
\kappa_{n+2}(n-1;k)=\sigma(n+2;k), \qquad n\in\mathbb{N},
\end{equation*}
and for every $n\in\mathbb{N}$ there is an $m\in\{0,\ldots,\left\lfloor(n-1)/2\right\rfloor\}$ such that
\begin{equation*}
\kappa_{n+4}(n-1-2m;k)=\sigma(n+4;k).
\end{equation*}
\end{enumerate}
If $k=1$, then $(ii)$, $(iii)$ and $(iv)$ are equivalent to
\begin{enumerate}\itemsep=0pt
\item[$(i')$] $P_n(x)=P_n^{(1/(2c_1)-3/2)}(x)$, $n\in\mathbb{N}_0$.
\end{enumerate}

\label{lma:last}
One has
\begin{enumerate}\itemsep=0pt
\item[$(i)$] $\alpha_n(n;k)=T_n(|\cos(\pi/k)|)/h(n)$, $n\in\mathbb{N}_0$,
\item[$(ii)$] the equation
\begin{equation*}
\alpha_n(n-2;k)=\frac{U_{n-2}\left(\left|\cos\left(\frac{\pi}{k}\right)\right|\right)\sin^2\left(\frac{\pi}{k}\right)\big(n-4\sum_{j=1}^{n-1}a_{j-1}c_j\big)}{2c_{n-1}c_n h(n)}
\end{equation*}
holds for all $n\geq2$,
\item[$(iii)$] $\sigma(n;k)=U_{n-1}(|\cos(\pi/k)|)/(c_n h(n))$, $n\in\mathbb{N}$.
\end{enumerate}

i) If one expands $P_n(x)$ as in \eqref{eq:connectionexpansion}, this is obvious from the definitions (in particular, use \eqref{eq:Akdef}).

(ii) Using \eqref{eq:Akdef}, \eqref{eq:connectionexpansion} and (i), we have
\begin{align*}
&\sum_{j=1}^{\lfloor\frac{n}{2}\rfloor}r_n(j)T_{n-2j}\left(\left|\cos\left(\frac{\pi}{k}\right)\right|\right)T_{n-2j}(x)\\
&\quad=\mathrm{A}_k P_n(x)-r_n(0)T_n\left(\left|\cos\left(\frac{\pi}{k}\right)\right|\right)T_n(x)\\
&\quad=\left[T_n\left(\left|\cos\left(\frac{\pi}{k}\right)\right|\right)r_n(1)+\alpha_n(n-2;k)h(n-2)r_{n-2}(0)\right]T_{n-2}(x)+R(x)
\end{align*}
for some $R(x)\in\mathbb{R}[x]$ with $\deg R(x)\leq n-3$; thus a comparison of the coefficients of~$T_{n-2}(x)$ and \eqref{eq:Chebrecurrencesim} yield
\begin{align*}
\alpha_n(n-2;k)h(n-2)r_{n-2}(0)&=\left[T_{n-2}\left(\left|\cos\left(\frac{\pi}{k}\right)\right|\right)-T_n\left(\left|\cos\left(\frac{\pi}{k}\right)\right|\right)\right]r_n(1)\\
&=2U_{n-2}\left(\left|\cos\left(\frac{\pi}{k}\right)\right|\right)\sin^2\left(\frac{\pi}{k}\right)r_n(1).
\end{align*}
Finally, since
\begin{equation*}
4a_{n-2}a_{n-1}r_n(1)=\Bigg[n-4\sum_{j=1}^{n-1}a_{j-1}c_j\Bigg]r_{n-2}(0)
\end{equation*}
(see the proof of \cite[Lemma 5.1]{IO11}) and $a_{n-2}a_{n-1}h(n-2)=c_{n-1}c_n h(n)$, we obtain the assertion.

(iii) While on the one hand one has
\begin{equation*}
\mathrm{D}_k P_n(x)=\sum_{j=0}^{\lfloor\frac{n}{2}\rfloor}r_n(j)U_{n-2j-1}\left(\left|\cos\left(\frac{\pi}{k}\right)\right|\right)U_{n-2j-1}(x)
\end{equation*}
by \eqref{eq:Dkdef}, on the other hand one has
\begin{align*}
\mathrm{D}_k P_n(x)&=\kappa_n(n-1;k)h(n-1)r_{n-1}(0)T_{n-1}(x)+R(x)\\
&=\frac{\kappa_n(n-1;k)h(n-1)r_{n-1}(0)}{2-\delta_{n,1}}U_{n-1}(x)+S(x)
\end{align*}
with polynomials $R(x),S(x)\in\mathbb{R}[x]$ with $\deg R(x),\deg S(x)\leq n-2$. Consequently, we have
\begin{equation*}
r_n(0)U_{n-1}\left(\left|\cos\left(\frac{\pi}{k}\right)\right|\right)=\frac{\kappa_n(n-1;k)h(n-1)r_{n-1}(0)}{2-\delta_{n,1}},
\end{equation*}
and as obviously $r_{n-1}(0)=(2-\delta_{n,1})a_{n-1}r_n(0)$ and $a_{n-1}h(n-1)=c_n h(n)$, the proof is complete (note that, by definition, $\kappa_n(n-1;k)=\sigma(n;k)$).

\label{lma:productrule}
One has
\begin{equation*}
\mathrm{D}_k[P(x)Q(x)]=\mathrm{D}_k P(x)\mathrm{A}_k Q(x)+\mathrm{A}_k P(x)\mathrm{D}_k Q(x), \qquad P(x),Q(x)\in\mathbb{R}[x].
\end{equation*}
Consequently,
\begin{align}\label{eq:recurrencekappasieved}
&a_n\kappa_{n+1}(j;k)+c_n\kappa_{n-1}(j;k)\nonumber\\
&\quad=\left|\cos\left(\frac{\pi}{k}\right)\right|[a_j\kappa_n(j+1;k)+c_j\kappa_n(j-1;k)]+\alpha_n(j;k), \qquad n,j\in\mathbb{N}_0.
\end{align}

ue to linearity, it clearly suffices to establish that
\begin{equation*}
\mathrm{D}_k[T_m(x)T_n(x)]=\mathrm{D}_k T_m(x)\mathrm{A}_k T_n(x)+\mathrm{A}_k T_m(x)\mathrm{D}_k T_n(x), \qquad m,n\in\mathbb{N}_0.
\end{equation*}
This, however, can easily be seen from the equations \eqref{eq:Dkdef}, \eqref{eq:Akdef}, \eqref{eq:mixedsecond} and \eqref{eq:mixedthird} by the computation
\begin{align*}
&\mathrm{D}_k T_m(x)\mathrm{A}_k T_n(x)+\mathrm{A}_k T_m(x)\mathrm{D}_k T_n(x)\\
&\quad=T_n\left(\left|\cos\left(\frac{\pi}{k}\right)\right|\right)U_{m-1}\left(\left|\cos\left(\frac{\pi}{k}\right)\right|\right)T_n(x)U_{m-1}(x)\\
&\quad\phantom{=}{}+T_m\left(\left|\cos\left(\frac{\pi}{k}\right)\right|\right)U_{n-1}\left(\left|\cos\left(\frac{\pi}{k}\right)\right|\right)T_m(x)U_{n-1}(x)\\
&\quad=\frac{1}{4}\left[U_{m+n-1}\left(\left|\cos\left(\frac{\pi}{k}\right)\right|\right)-U_{n-m-1}\left(\left|\cos\left(\frac{\pi}{k}\right)\right|\right)\right][U_{m+n-1}(x)-U_{n-m-1}(x)]\\
&\quad\phantom{=}{}+\frac{1}{4}\left[U_{m+n-1}\left(\left|\cos\left(\frac{\pi}{k}\right)\right|\right)+U_{n-m-1}\left(\left|\cos\left(\frac{\pi}{k}\right)\right|\right)\right][U_{m+n-1}(x)+U_{n-m-1}(x)]\\
&\quad=\frac{1}{2}U_{m+n-1}\left(\left|\cos\left(\frac{\pi}{k}\right)\right|\right)U_{m+n-1}(x)+\frac{1}{2}U_{n-m-1}\left(\left|\cos\left(\frac{\pi}{k}\right)\right|\right)U_{n-m-1}(x)\\
&\quad=\frac{1}{2}\mathrm{D}_k T_{m+n}(x)+\frac{1}{2}\mathrm{D}_k T_{n-m}(x)=\mathrm{D}_k\left[\frac{1}{2}T_{m+n}(x)+\frac{1}{2}T_{n-m}(x)\right]\\
&\quad=\mathrm{D}_k[T_m(x)T_n(x)]
\end{align*}
for $m\leq n$ (the expansion $T_m(x)T_n(x)=T_{m+n}(x)/2+T_{n-m}(x)/2$ is well known). Now let $n,j\in\mathbb{N}_0$. Via \eqref{eq:recfund}, we compute
\begin{align*}
a_n\mathrm{D}_k P_{n+1}(x)+c_n\mathrm{D}_k P_{n-1}(x)&=\mathrm{D}_k[x P_n(x)]\\
&=\mathrm{D}_k[x]\mathrm{A}_k P_n(x)+\mathrm{A}_k[x]\mathrm{D}_k P_n(x)\\
&=\left|\cos\left(\frac{\pi}{k}\right)\right|x \mathrm{D}_k P_n(x)+\mathrm{A}_k P_n(x);
\end{align*}
multiplication with $P_j(x)$, integration with respect to $\mu$ and the equations \eqref{eq:kappandeffirst} and \eqref{eq:alphandeffirst} yield the second assertion.

he case $k=1$ is trivial because $\mathrm{A}_1=\mathrm{id}$, so let $k\geq2$ from now on (in particular, we then have $|\cos(\pi/k)|=\cos(\pi/k)$). ``(i) $\Rightarrow$ (ii)'': let $n\in\mathbb{N}_0$ and $i\in\{0,\ldots,k-1\}$. Using Theorem~\ref{thm:mainsieved} and \eqref{eq:Akdef}, we have
\begin{align*}
&T_{k n+i}\left(\cos\left(\frac{\pi}{k}\right)\right)P_{k n+i}(x;k)-\mathrm{A}_k P_{k n+i}(x;k)\\
&\quad=\sum_{j=0}^{\lfloor\frac{n}{2}\rfloor}p_n(j)\left[T_{k n+i}\left(\cos\left(\frac{\pi}{k}\right)\right)-T_{k n-2j k-i}\left(\cos\left(\frac{\pi}{k}\right)\right)\right]T_{k n-2j k-i}(x)\\
&\quad\phantom{=}{}+\sum_{j=0}^{\lfloor\frac{n}{2}\rfloor}q_n(j)\left[T_{k n+i}\left(\cos\left(\frac{\pi}{k}\right)\right)-T_{k n-2j k+i}\left(\cos\left(\frac{\pi}{k}\right)\right)\right]T_{k n-2j k+i}(x).
\end{align*}
For each $j\in\{0,\ldots,\left\lfloor n/2\right\rfloor\}$ (except the case $n$ even and $j=n/2$, but then $p_n(j)=0$), we compute
\begin{align*}
T_{k n+i}\left(\cos\left(\frac{\pi}{k}\right)\right)-T_{k n-2j k-i}\left(\cos\left(\frac{\pi}{k}\right)\right)&=\cos\left(\frac{(k n+i)\pi}{k}\right)-\cos\left(\frac{(k n-2j k-i)\pi}{k}\right)\\
&=-2\sin((n-j)\pi)\sin\left(\frac{(j k+i)\pi}{k}\right)\\
&=0.
\end{align*}
In the same way, we have
\begin{equation*}
T_{k n+i}\left(\cos\left(\frac{\pi}{k}\right)\right)-T_{k n-2j k+i}\left(\cos\left(\frac{\pi}{k}\right)\right)=0
\end{equation*}
for all $j\in\{0,\ldots,\left\lfloor n/2\right\rfloor\}$. Hence, we see that $P_{k n+i}(x;k)$ is an eigenvector of $\mathrm{A}_k$ which corresponds to the eigenvalue $T_{k n+i}(\cos(\pi/k))$. ``(ii) $\Rightarrow$ (iii)'' is trivial from orthogonality. \text{``(iii) $\Rightarrow$ (i)''}: the condition and Lemma~\ref{lma:last} yield
\begin{equation}\label{eq:centralequation}
4\sum_{j=1}^n a_{j-1}c_j=n+1\quad \text{if}\quad k\,{\not|}\, n\in\mathbb{N}.
\end{equation}
It is immediate from \eqref{eq:centralequation} that $c_1=1/2$. Let $n\in\mathbb{N}$ be such that $k$ does not divide $n+1$. Moreover, assume that, for each $j\in\{1,\ldots,n\}$, $c_j=1/2$ if $j$ is not a multiple of $k$. Decomposing $n+1=k l+i$ with unique $l\in\mathbb{N}_0$, $i\in\{1,\ldots,k-1\}$, on the one hand, we get
\begin{equation*}
k l+i+1=4\sum_{j=1}^{k l+i}a_{j-1}c_j=4\sum_{j=1}^{k l}a_{j-1}c_j+4\sum_{j=k l+1}^{k l+i}a_{j-1}c_j=k l+2c_{k l}+4\sum_{j=k l+1}^{k l+i}a_{j-1}c_j
\end{equation*}
from \eqref{eq:centralequation}, which then simplifies to
\begin{equation}\label{eq:centrallemmafirst}
\frac{c_{k l}}{2}+\sum_{j=k l+1}^{k l+i}a_{j-1}c_j=\frac{i+1}{4}.
\end{equation}
On the other hand, we compute
\begin{equation}\label{eq:centrallemmasecond}
\frac{c_{k l}}{2}+\sum_{j=k l+1}^{k l+i}a_{j-1}c_j=\begin{cases} \dfrac{c_{k l}}{2}+a_{k l}c_{k l+1}, & i=1, \vspace{1mm}\\
 \dfrac{i}{4}+\dfrac{c_{k l+i}}{2}, & \text{else}. \end{cases}
\end{equation}
Combining \eqref{eq:centrallemmafirst} and \eqref{eq:centrallemmasecond}, we obtain that $c_{n+1}=c_{k l+i}=1/2$. This finishes the proof of \text{``(iii) $\Rightarrow$ (i)''}. Concerning the remaining assertion, it suffices to show that \[P_n(\cos(\pi/k);k)=T_n(\cos(\pi/k)),\qquad n\in\mathbb{N}_0;\]
this can be seen as follows: let $l\in\mathbb{N}_0$. Since $T_{k l}(\cos(\pi/k))=(-1)^l$, and since
\begin{equation*}
T_{k l-1}\left(\cos\left(\frac{\pi}{k}\right)\right)=(-1)^l\cos\left(\frac{\pi}{k}\right)=T_{k l+1}\left(\cos\left(\frac{\pi}{k}\right)\right)
\end{equation*}
for $l\neq0$, we have
\begin{equation*}
\cos\left(\frac{\pi}{k}\right)T_{k l}\left(\cos\left(\frac{\pi}{k}\right)\right)=a_l T_{k l+1}\left(\cos\left(\frac{\pi}{k}\right)\right)+c_l T_{k l-1}\left(\cos\left(\frac{\pi}{k}\right)\right).
\end{equation*}
Consequently, the recurrence relations for the sequences \[(P_n(\cos(\pi/k);k))_{n\in\mathbb{N}_0}\qquad \text{and}\qquad (T_n(\cos(\pi/k)))_{n\in\mathbb{N}_0}\] coincide.

irst, note that in view of \eqref{eq:kernelstarprior} (iii) is an obvious reformulation of~(ii). Moreover, the case $k=1$ is just Theorem~\ref{thm:lasserobermaierref} because $\mathrm{D}_1=\mathrm{d}/\mathrm{d}x$ (concerning (iv), we refer to the proof given in \cite{LO08}), so let $k\geq2$ from now on. ``(i) $\Rightarrow$ (ii)'': we know from Theorem~\ref{thm:mainsievedaveraging} \text{``(i) $\Rightarrow$ (ii)''} and Lemma~\ref{lma:productrule} that
\begin{align}
&a_n\kappa_{n+1}(j;k)+c_n\kappa_{n-1}(j;k)\nonumber\\
&\quad=\cos\left(\frac{\pi}{k}\right)[a_j\kappa_n(j+1;k)+c_j\kappa_n(j-1;k)]+T_n\left(\cos\left(\frac{\pi}{k}\right)\right)\frac{\delta_{n,j}}{h(n)}, \qquad n,j\in\mathbb{N}_0,\label{eq:productrulespecial}
\end{align}
and we now use induction on $n$ to deduce that
\begin{equation}\label{eq:kappaind}
\kappa_n(n-1-2j;k)=\frac{U_{n-1}\left(\cos\left(\frac{\pi}{k}\right)\right)}{c_n h(n)}, \qquad j\in\left\{0,\ldots,\left\lfloor\frac{n-1}{2}\right\rfloor\right\}
\end{equation}
for each $n\in\mathbb{N}$, which implies the assertion due to \eqref{eq:kernelstarprior} and \eqref{eq:kappandefsecond}. It is obvious from Lemma~\ref{lma:last} that \eqref{eq:kappaind} is satisfied for $n\in\{1,2\}$, so let $n\in\mathbb{N}\backslash\{1\}$ be arbitrary but fixed now and assume~\eqref{eq:kappaind} to hold for both $n-1$ and $n$. If $j\in\{1,\ldots,\left\lfloor n/2\right\rfloor\}$, then \eqref{eq:productrulespecial} implies
\begin{equation}\label{eq:threecases}
c_{n+1}h(n+1)\kappa_{n+1}(n-2j;k)=\cos\left(\frac{\pi}{k}\right)\frac{U_{n-1}\left(\cos\left(\frac{\pi}{k}\right)\right)}{c_n}-U_{n-2}\left(\cos\left(\frac{\pi}{k}\right)\right)\frac{a_{n-1}}{c_{n-1}},
\end{equation}
and we distinguish two cases: if $k\,{\not|}\,n$, then \eqref{eq:threecases} yields
\begin{equation*}
c_{n+1}h(n+1)\kappa_{n+1}(n-2j;k)=2\cos\left(\frac{\pi}{k}\right)U_{n-1}\left(\cos\left(\frac{\pi}{k}\right)\right)-U_{n-2}\left(\cos\left(\frac{\pi}{k}\right)\right)
\end{equation*}
because $a_{n-1}=c_{n-1}=1/2$ (if $k\,{\not|}\,(n-1)$) or $U_{n-2}(\cos(\pi/k))=0$ (if $k|(n-1)$), which, by the recurrence relation for the Chebyshev polynomials of the second kind, simplifies to
\begin{equation*}
c_{n+1}h(n+1)\kappa_{n+1}(n-2j;k)=U_n\left(\cos\left(\frac{\pi}{k}\right)\right).
\end{equation*}
If $k|n$, however, we compute from \eqref{eq:threecases}
\begin{gather*}
c_{n+1}h(n+1)\kappa_{n+1}(n-2j;k)=-U_{n-2}\left(\cos\left(\frac{\pi}{k}\right)\right)=U_n\left(\cos\left(\frac{\pi}{k}\right)\right).
\end{gather*}
If one takes into account Lemma~\ref{lma:last} for the remaining case ``$j=0$'' again, the proof of the direction ``(i) $\Rightarrow$ (ii)'' is finished. ``(ii) $\Rightarrow$ (iv)'' is trivial from \eqref{eq:kernelstarprior}. The direction \text{``(iv) $\Rightarrow$ (i)''} is more involved; we first deal with $c_1$ and $c_2$: due to the conditions $\kappa_3(0;k)=\sigma(3;k)$ and $\kappa_4(1;k)=\sigma(4;k)$, a tedious but straightforward calculation based on Lemmas~\ref{lma:last} and~\ref{lma:productrule} yields
\begin{gather}\label{eq:initialfirst}
U_2\left(\cos\left(\frac{\pi}{k}\right)\right)[1-4c_1+4c_1c_2]=3-4c_1-4c_2+4c_1c_2
\end{gather}
and
\begin{align*}
&\cos\left(\frac{\pi}{k}\right)U_2\left(\cos\left(\frac{\pi}{k}\right)\right)[3-4c_1-8c_2+4c_1c_2+8c_2c_3]\\
&\quad=\cos\left(\frac{\pi}{k}\right)[9-12c_1-12c_2-8c_3+12c_1c_2+16c_2c_3].
\end{align*}
Combining these equations, we obtain
\begin{equation}\label{eq:initialfourth}
\cos\left(\frac{\pi}{k}\right)U_2\left(\cos\left(\frac{\pi}{k}\right)\right)[c_1-c_2-c_1c_2+c_2c_3]=\cos\left(\frac{\pi}{k}\right)[-c_3+2c_2c_3].
\end{equation}
To get another equation for $c_1$, $c_2$, $c_3$, we first note that Lemma~\ref{lma:last} and \eqref{eq:Chebrecurrencesim} imply that
\begin{align*}
\mathrm{A}_k P_4(x)={}&T_4\left(\cos\left(\frac{\pi}{k}\right)\right)P_4(x)\\
&+\left[T_2\left(\cos\left(\frac{\pi}{k}\right)\right)-T_4\left(\cos\left(\frac{\pi}{k}\right)\right)\right]\frac{a_1-c_3}{a_3}P_2(x)+\alpha_4(0;k)\\
={}&T_4\left(\cos\left(\frac{\pi}{k}\right)\right)[P_4(x)-1]\\&+\left[T_2\left(\cos\left(\frac{\pi}{k}\right)\right)-T_4\left(\cos\left(\frac{\pi}{k}\right)\right)\right]\frac{a_1-c_3}{a_3}[P_2(x)-1]+\mathrm{A}_k P_4(1),
\end{align*}
which, since
\begin{equation*}
P_4(x)=\frac{1}{8a_1a_2a_3}T_4(x)+\frac{a_1-c_3}{2a_1a_3}T_2(x)+\frac{8a_1a_2a_3-4a_1a_2+4a_2c_3-1}{8a_1a_2a_3}
\end{equation*}
due to \eqref{eq:recfund}, becomes
\begin{align}
\mathrm{A}_k P_4(x)={}&T_4\left(\cos\left(\frac{\pi}{k}\right)\right)P_4(x)+\left[T_2\left(\cos\left(\frac{\pi}{k}\right)\right) -T_4\left(\cos\left(\frac{\pi}{k}\right)\right)\right]\frac{a_1-c_3}{a_3}P_2(x)\nonumber\\
&+\left[T_4\left(\cos\left(\frac{\pi}{k}\right)\right)-1\right]\left[\frac{1}{8a_1a_2a_3}-1\right]-\left[1-T_2\left(\cos\left(\frac{\pi}{k}\right)\right)\right]
\frac{a_1-c_3}{2a_1a_3}\nonumber\\
&-\left[T_2\left(\cos\left(\frac{\pi}{k}\right)\right)-T_4\left(\cos\left(\frac{\pi}{k}\right)\right)\right]\frac{a_1-c_3}{a_3}\label{eq:initialthirdpre}
\end{align}
after another tedious but straightforward calculation which uses \eqref{eq:Akdef}. We then take into account that Lemma~\ref{lma:productrule} and the conditions $\kappa_3(0;k)=\sigma(3;k)$, $\kappa_4(1;k)=\sigma(4;k)$ and $\kappa_5(0;k)=\kappa_5(2;k)(=\sigma(5;k))$ yield $\alpha_4(0;k)=\alpha_4(2;k)$, which can be rewritten as
\begin{align}
&U_2\left(\cos\left(\frac{\pi}{k}\right)\right)\big[1-8c_1+8c_1^2+16c_1c_2-16c_1^2c_2-8c_1c_2^2-8c_1c_2c_3+8c_1^2c_2^2+8c_1c_2^2c_3\big]\nonumber\\
&\quad=3-4c_1-4c_2-4c_3+4c_1c_2+8c_1c_3+4c_2c_3-8c_1c_2c_3\label{eq:initialthird}
\end{align}
as a consequence of \eqref{eq:initialthirdpre} and the simplifications
\begin{align*}
&T_2\left(\cos\left(\frac{\pi}{k}\right)\right)-T_4\left(\cos\left(\frac{\pi}{k}\right)\right)=2U_2\left(\cos\left(\frac{\pi}{k}\right)\right)\sin^2\left(\frac{\pi}{k}\right),\\
&T_4\left(\cos\left(\frac{\pi}{k}\right)\right)-1=-\left[2U_2\left(\cos\left(\frac{\pi}{k}\right)\right)+2\right]\sin^2\left(\frac{\pi}{k}\right),\\
&1-T_2\left(\cos\left(\frac{\pi}{k}\right)\right)=2\sin^2\left(\frac{\pi}{k}\right).
\end{align*}
Now, the combination of \eqref{eq:initialfirst} with \eqref{eq:initialthird} gives
\begin{align*}
&U_2\left(\cos\left(\frac{\pi}{k}\right)\right)\big[c_1-2c_1^2-3c_1c_2+4c_1^2c_2+2c_1c_2^2+2c_1c_2c_3-2c_1^2c_2^2-2c_1c_2^2c_3\big]\\
&\quad=c_3-2c_1c_3-c_2c_3+2c_1c_2c_3;
\end{align*}
dividing this by $1-c_2$, we finally obtain
\begin{equation}\label{eq:initialfifth}
U_2\left(\cos\left(\frac{\pi}{k}\right)\right)\big[c_1-2c_1^2-2c_1c_2+2c_1^2c_2+2c_1c_2c_3\big]=c_3-2c_1c_3.
\end{equation}
From now on, we consider the nonlinear system \eqref{eq:initialfirst}, \eqref{eq:initialfourth}, \eqref{eq:initialfifth}, which depends on $k$. If $k=2$, then \eqref{eq:initialfirst} immediately gives $c_1=1/2$ because $U_2(0)=-1$. In the following, let $k\geq3$; here, $\cos(\pi/k)\neq0$ and \eqref{eq:initialfourth} reduces to
\begin{equation}\label{eq:initialfourthred}
U_2\left(\cos\left(\frac{\pi}{k}\right)\right)[c_1-c_2-c_1c_2+c_2c_3]=-c_3+2c_2c_3.
\end{equation}
Combining \eqref{eq:initialfirst} and \eqref{eq:initialfifth}, we see that
\begin{align}
&[3-4c_1-4c_2+4c_1c_2]\big[c_1-2c_1^2-2c_1c_2+2c_1^2c_2+2c_1c_2c_3\big]\nonumber\\
&\quad=U_2\left(\cos\left(\frac{\pi}{k}\right)\right)[1-4c_1+4c_1c_2]\big[c_1-2c_1^2-2c_1c_2+2c_1^2c_2+2c_1c_2c_3\big]\nonumber\\
&\quad=[1-4c_1+4c_1c_2][c_3-2c_1c_3].\label{eq:initialI}
\end{align}
In the same way combining \eqref{eq:initialfirst}, \eqref{eq:initialfourthred} on the one hand and \eqref{eq:initialfifth}, \eqref{eq:initialfourthred} on the other hand, we get
\begin{align*}
&[3-4c_1-4c_2+4c_1c_2][c_1-c_2-c_1c_2+c_2c_3]=[1-4c_1+4c_1c_2][-c_3+2c_2c_3],\\
&[c_3-2c_1c_3][c_1-c_2-c_1c_2+c_2c_3]=\big[c_1-2c_1^2-2c_1c_2+2c_1^2c_2+2c_1c_2c_3\big][-c_3+2c_2c_3],
\end{align*}
which can be rewritten as
\begin{align}
&\big[1-4c_1+c_2+8c_1c_2-4c_2^2-4c_1c_2^2\big]c_3\nonumber\\
&\quad=-3c_1+3c_2+4c_1^2+3c_1c_2-4c_2^2-8c_1^2c_2+4c_1^2c_2^2,\label{eq:initialIIadd} \\
&\big[c_2-4c_1c_2^2\big]c_3=-2c_1+c_2+4c_1^2+3c_1c_2-8c_1^2c_2-4c_1c_2^2+4c_1^2c_2^2.\label{eq:initialII}
\end{align}
Moreover, we can deduce from \eqref{eq:initialIIadd} and \eqref{eq:initialII} that
\begin{align*}
&\big[-3c_1+3c_2+4c_1^2+3c_1c_2-4c_2^2-8c_1^2c_2+4c_1^2c_2^2\big]\big[c_2-4c_1c_2^2\big]\\
&\quad=\big[1-4c_1+c_2+8c_1c_2-4c_2^2-4c_1c_2^2\big]c_3\big[c_2-4c_1c_2^2\big]\\
&\quad=\big[1-4c_1+c_2+8c_1c_2-4c_2^2-4c_1c_2^2\big]\\
&\phantom{\quad=}{}\times\big[-2c_1+c_2+4c_1^2+3c_1c_2-8c_1^2c_2-4c_1c_2^2+4c_1^2c_2^2\big],
\end{align*}
which now considerably simplifies to
\begin{equation*}
[4c_1c_2-4c_1+1][2c_1c_2-2c_1+c_2][2c_2-1][2c_1-1]=0.
\end{equation*}
If $4c_1c_2-4c_1+1=0$, it is immediate from \eqref{eq:initialfirst} that $c_2=1/2$. If $2c_1c_2-2c_1+c_2=0$, then~\eqref{eq:initialfirst} reads $U_2(\cos(\pi/k))[1-2c_2]=3-6c_2$, and we can conclude that $c_2=1/2$, too \big(because $U_2(\cos(\pi/k))=4(\cos(\pi/k))^2-1<3$\big). If $c_2=1/2$, then \eqref{eq:initialII} reduces to $(1-2c_1)(1-c_1-c_3)=0$, and if additionally $c_3=1-c_1$, then \eqref{eq:initialI} implies that $c_1=1/2$. Finally, if $c_1=1/2$, then~${c_2=1/2}$ because otherwise \eqref{eq:initialfirst} would yield ${-1\!=\!U_2(\cos(\pi/k))\!=\!\sin(3\pi/k)/\sin(\pi/k)\!\geq\!0}$. Therefore, allowing $k\geq2$ to be arbitrary again, we have seen that $c_1=1/2$ in each possible case, and that $c_2=1/2$ if $k\neq2$. Now let $n\in\mathbb{N}\backslash\{1\}$ be arbitrary but fixed and assume that, for all $j\in\{1,\ldots,n\}$, $c_j=1/2$ if $j$ is not a multiple of $k$. Lemma~\ref{lma:productrule} and the conditions $\kappa_{n+1}(n-2;k)=\sigma(n+1;k)$ and $\kappa_{n+2}(n-1;k)=\sigma(n+2;k)$ yield
\begin{equation}\label{eq:indsaw1}
a_{n+1}\sigma(n+2;k)+c_{n+1}\sigma(n;k)=\cos\left(\frac{\pi}{k}\right)\sigma(n+1;k)+\alpha_{n+1}(n-1;k).
\end{equation}
Since $\alpha_{n+1}(n-1;k)$ is uniquely determined by the recurrence coefficients $c_1,\ldots,c_n$ (which is already a consequence of \eqref{eq:alphandefsecond}), we have $\alpha_{n+1}(n-1;k)=0$ by Theorem~\ref{thm:mainsievedaveraging} ``(i) $\Rightarrow$ (ii)'' and the induction hypothesis.\footnote{Such arguments will occur several times in our proof, so we give some more details at this stage: compare $(P_j(x))_{j\in\mathbb{N}_0}$ to the sequence \smash{$\big(\widetilde{P}_j(x)\big)_{j\in\mathbb{N}_0}$} which is given by $\widetilde{c}_j:=c_j$ for $j\in\{1,\ldots,n\}$ and $\widetilde{c}_j:=1/2$ otherwise. Then \smash{$\big(\widetilde{P}_j(x)\big)_{j\in\mathbb{N}_0}$} is $k$-sieved, so $0=\widetilde{\alpha}_{n+1}(n-1;k)=\alpha_{n+1}(n-1;k)$. We used similar ideas also in our paper~\cite{Ka16a}.} Therefore, \eqref{eq:indsaw1} simplifies to
\begin{equation*}
a_{n+1}\sigma(n+2;k)+c_{n+1}\sigma(n;k)=\cos\left(\frac{\pi}{k}\right)\sigma(n+1;k),
\end{equation*}
and then multiplication with $a_n c_n h(n)$, Lemma~\ref{lma:last} and the recurrence relation for the Chebyshev polynomials of the second kind imply that
\begin{equation}\label{eq:indsaw2}
\cos\left(\frac{\pi}{k}\right)U_n\left(\cos\left(\frac{\pi}{k}\right)\right)(1-2c_{n+1})c_n=U_{n-1}\left(\cos\left(\frac{\pi}{k}\right)\right)(1-2c_n)c_{n+1}.
\end{equation}
If $k\geq3$ and if $n+1$ is not a multiple of $k$, then $\cos(\pi/k)U_n(\cos(\pi/k))\neq0$; consequently, \eqref{eq:indsaw2} tells $c_{n+1}=1/2$ because $U_{n-1}(\cos(\pi/k))=0$ or $c_n=1/2$, depending on whether $k$ divides $n$ or not. The case $k=2$ is more involved---here, \eqref{eq:indsaw2} does not allow for any conclusion. Instead, we apply an idea which we similarly used in \cite{Ka16a} (at that time for the operators $\mathcal{D}_q$ and $\mathcal{A}_q$; cf. particularly \cite[Lemma 3.1, proof of Theorem 2.3]{Ka16a}) and proceed as follows: by the conditions, there is some $m\in\{0,\ldots,\left\lfloor(n-2)/2\right\rfloor\}$ such that ${\kappa_{n+3}(n-2-2m;2)=\sigma(n+3;2)}$. Since $c_1,\ldots,c_n$ fix the first $n+2$ polynomials $P_0(x),\ldots,P_{n+1}(x)$, $c_1,\ldots,c_n$ yield unique $\lambda_0,\ldots,\lambda_{n+2},\nu_0,\ldots,\nu_{n-1}\in\mathbb{R}$ such that
\begin{align*}
\mathrm{A}_2[x P_{n+1}(x)]={}&\lambda_0+x\sum_{j=0}^{n+1}\lambda_{j+1}P_j(x)\\
={}&\lambda_0+\lambda_2c_1+\sum_{j=1}^n[\lambda_j a_{j-1}+\lambda_{j+2}c_{j+1}]P_j(x)\\
&+\lambda_{n+1}a_n P_{n+1}(x)+\lambda_{n+2}a_{n+1} P_{n+2}(x)\\
={}&\sum_{j=0}^{n-1}\nu_j P_j(x)+[\lambda_n a_{n-1}+\lambda_{n+2}c_{n+1}]P_n(x)\\
&+\lambda_{n+1}a_n P_{n+1}(x)+\lambda_{n+2}a_{n+1} P_{n+2}(x).
\end{align*}
Therefore, $c_1,\ldots,c_n$ determine the integral
\begin{equation*}
\int_\mathbb{R}\!\mathrm{A}_2[x P_{n+1}(x)]P_{n-2-2m}(x)\,\mathrm{d}\mu(x)=\frac{\nu_{n-2-2m}}{h(n-2-2m)}
\end{equation*}
uniquely, so \eqref{eq:recfund} and Theorem~\ref{thm:mainsievedaveraging} ``(i) $\Rightarrow$ (ii)'' imply that
\begin{equation*}
\int_\mathbb{R}\!\mathrm{A}_2[x P_{n+1}(x)]P_{n-2-2m}(x)\,\mathrm{d}\mu(x)=0
\end{equation*}
as a consequence of the induction hypothesis. Hence, using Theorem~\ref{thm:mainsievedaveraging} ``(i) $\Rightarrow$ (ii)'' again, \eqref{eq:recfund} and the fact that $\alpha_n(n-2-2m;2)$ is uniquely determined by $c_1,\ldots,c_n$, too (use \eqref{eq:alphandefsecond}), we see that
\begin{equation}\label{eq:alphaequalI}
0=a_{n+1}\alpha_{n+2}(n-2-2m;2)+c_{n+1}\alpha_n(n-2-2m;2)=a_{n+1}\alpha_{n+2}(n-2-2m;2).
\end{equation}
Furthermore, we have
\begin{equation}\label{eq:alphaequalII}
\alpha_{n+2}(n-2-2m;2)=\alpha_{n+2}(n;2),
\end{equation}
which can be seen as follows: on the one hand, since $\kappa_{n+1}(n-2-2m;2)$ is uniquely determined by $c_1,\ldots,c_n$ (this is a consequence of \eqref{eq:kappandefsecond}), one has $\kappa_{n+1}(n-2-2m;2)=\sigma(n+1;2)$ by the already established direction ``(i) $\Rightarrow$ (ii)''; hence, by Lemma~\ref{lma:productrule} we have
\begin{equation*}
a_{n+2}\sigma(n+3;2)+c_{n+2}\sigma(n+1;2)=\alpha_{n+2}(n-2-2m;2).
\end{equation*}
On the other hand, by Lemma~\ref{lma:productrule} and the condition $\kappa_{n+3}(n;2)=\sigma(n+3;2)$, we have
\begin{equation*}
a_{n+2}\sigma(n+3;2)+c_{n+2}\sigma(n+1;2)=\alpha_{n+2}(n;2),
\end{equation*}
so \eqref{eq:alphaequalII} is established. Combining \eqref{eq:alphaequalII} with \eqref{eq:alphaequalI}, we obtain that
\begin{equation*}
\alpha_{n+2}(n;2)=0.
\end{equation*}
Now following the proof of Theorem~\ref{thm:mainsievedaveraging} ``(iii) $\Rightarrow$ (i)'', we can conclude that $c_{n+1}=1/2$ if $n+1$ is odd, which finishes the proof of Theorem~\ref{thm:mainsievedaskeywilson}.
